import { policyHash } from './phrase-policy.ts';
import { escapeHtml as e } from './operations-page.ts';
import type { PreparationView } from './preparation.ts';
import { researchCandidateReason } from './preparation.ts';
import type { DirectView } from './direct.ts';
import { hasUnresolvedDirect } from './direct-pending.ts';
import { descriptionHash, profileHash, judgmentHash, selectionHash } from './campaign-plan.ts';
import { researchRequests } from './phrase-strategy.ts';
const hidden = (key: string, value: string | number) => `<input type="hidden" name="${key}" value="${e(String(value))}">`;
const check = (name: string, text: string) => `<label class="check"><input type="checkbox" name="${name}" value="yes">${text}</label>`;
export function renderPlan(view: PreparationView, scope: string, direct?: DirectView) {
  const p = view.saved.value, step = p.step, errors = view.errors ?? {};
  const labels = { description: 'Описание бизнеса', url: 'Адрес посадочной страницы', region: 'Регион', goal: 'Что хотите получить от рекламы',
    budget: 'Общий лимит, ₽', period: 'Период бюджета', title: 'Заголовок объявления', adText: 'Текст объявления' };
  const values = { ...p.input, goal: p.goal };
  function field(name: string, label: string, value: string, kind = 'input', hint = '', required = false, max = 1000) {
    const id = 'plan-' + name, error = errors[name];
    const attrs = `id="${id}" name="${name}"${required ? ' required' : ''} maxlength="${max}"${error ? ' aria-invalid="true"' : ''} aria-describedby="${id}-hint${error ? ' ' + id + '-error' : ''}"`;
    const input = kind === 'textarea' ? `<textarea ${attrs} rows="3">${e(value)}</textarea>` : kind === 'period'
      ? `<select ${attrs}>${['7', '30'].map(s => `<option value="${s}"${value === s ? ' selected' : ''}>${s} дней</option>`).join('')}</select>`
      : `<input ${attrs} type="${name === 'url' ? 'url' : 'text'}"${name === 'budget' ? ' inputmode="numeric"' : ''} value="${e(value)}">`;
    return `<div class="field"><label for="${id}">${e(label)}</label>${input}<p class="hint" id="${id}-hint">${hint}</p>${error ? `<p class="field-error" id="${id}-error">${e(error)}</p>` : ''}</div>`;
  }
  const inputField = (name: keyof typeof values, hint = '') => field(name, labels[name], values[name], ['description', 'adText'].includes(name) ? 'textarea' : name === 'period' ? 'period' : 'input', hint, true,
    name === 'description' ? 1000 : name === 'adText' ? 81 : name === 'title' ? 56 : name === 'goal' ? 160 : name === 'url' ? 2048 : 100);
  const post = (action: string, label: string, primary = false, extra = '') => `<button type="submit" formaction="/preparation/${action}" class="${primary ? 'primary' : 'secondary'}"${extra}>${label}</button>`;
  const back = (n: number, label = 'Назад') => post('back', label, false, ` name="step" value="${n}" formnovalidate`);
  const freshProposal = view.run?.kind === 'profile' && view.run.profileHash === descriptionHash(p.input.description) ? view.run.plan.strategy.profile : undefined;
  const profile = p.profile?.value.offers.length ? p.profile.value : freshProposal;
  const usable = view.run && ['research','derived','rejudge'].includes(view.run.kind) && view.run.profileHash === profileHash(p) && view.run.judgmentHash === judgmentHash(p);
  const candidates = usable ? view.run!.plan.strategy.candidates : [];
  const selected = p.selection.checkedHash === selectionHash(p) ? p.selection.phrases : view.run?.plan.policyHash === policyHash ? candidates.filter(c => c.selected).map(c => c.phrase) : [];
  const profileCurrent = p.profile?.confirmedHash === profileHash(p);
  const visible: (keyof typeof values)[] = step === 1 ? ['description', 'url', 'region', 'goal', 'budget', 'period'] : step === 2 ? ['description'] : step === 3 ? ['title', 'adText'] : [];
  const comparison = view.latest ? [
    ...Object.entries(labels).map(([key,label]) => [label, key === 'goal' ? view.latest!.goal : view.latest!.input[key], values[key]]),
    ['Предложения', view.latest.profile?.value.offers.map(o=>o.name + ' · ' + o.evidence).join('; ') ?? '', p.profile?.value.offers.map(o=>o.name + ' · ' + o.evidence).join('; ') ?? ''],
    ['Фразы', view.latest.selection.phrases.join('; '), p.selection.phrases.join('; ')]
  ].filter(([,a,b])=>a!==b) : [];
  const campaignComparison = view.campaign ? Object.entries(labels).filter(([key]) => key !== 'goal').map(([key,label]) => [label, view.campaign!.draft[key], values[key]]).filter(([,a,b])=>a!==b) : [];
  const comparisonTable = (rows: string[][], label: string, empty: string) => rows.length ? `<div class="table-scroll" tabindex="0" role="region" aria-label="${e(label)}"><table><thead><tr><th>Поле</th><th>Сохранено сейчас</th><th>Ваш ввод</th></tr></thead><tbody>${rows.map(([name,a,b])=>`<tr><th>${e(name)}</th><td>${e(a ?? '')}</td><td>${e(b ?? '')}</td></tr>`).join('')}</tbody></table></div>` : `<p>${empty}</p>`;
  const state = view.unsaved ? 'Есть несохранённые изменения' : view.current ? 'План подтверждён' : view.saved.revision ? 'Рабочий ввод сохранён' : 'Подготовка ещё не сохранена';
  const fixture = direct?.mode === 'fixture';
  const budgetNote = direct?.ownChief
    ? 'Общий лимит плана будет проверен как бюджет стратегии API на выбранный период без автопродления. Бюджет стратегии не является суммой счёта или гарантией фактического расхода.'
    : direct?.enabled ? 'Недельный параметр API будет проверен отдельно: общий лимит не становится ограничением фактического расхода Директа.'
    : 'Параметры бюджета API проверяются отдельно перед созданием. Общий лимит плана пока не ограничивает фактический расход Директа.';
  const source = p.profile?.origin === 'ai' ? 'Предложение DeepSeek · проверено владельцем' : p.profile?.origin === 'mixed' ? 'DeepSeek и ручные исправления' : freshProposal && !p.profile?.value.offers.length ? 'Предложение DeepSeek · ещё не подтверждено' : 'Ручное понимание бизнеса';
  return `<div class="page-heading"><div><h1>Подготовка кампании</h1><p class="lead">От описания бизнеса к одному проверенному плану. Создание рекламы — отдельное действие.</p></div><p id="save-state" class="save-state" role="status">${state}</p></div>
  ${view.legacy ? '<p class="source-note">Сохранённый прежний черновик и его история на месте. Перед новым созданием проверьте понимание и подтвердите план.</p>' : ''}
  ${fixture ? '<p class="source-note">Проверочный стенд: DeepSeek, Wordstat и Директ подставлены. Настоящих платных вызовов и рекламных записей нет.</p>' : ''}
  <div class="notice recovery" id="recovery" hidden><p>В этой вкладке остался несохранённый ввод подготовки.</p><button type="button" id="restore-work" class="secondary">Восстановить ввод</button><button type="button" id="discard-work" class="text-button">Удалить сохранённый ввод</button></div>
  <ol class="steps plan-steps" aria-label="Подготовка кампании">${['Бизнес и условия', 'Что мы поняли', 'Рекламное предложение', 'Проверка и создание'].map((label, i) => `<li${step === i + 1 ? ' aria-current="step"' : ''}><span class="number">${i + 1}</span>${i + 1 < step ? `<button type="submit" form="campaign-form" name="step" value="${i + 1}" formaction="/preparation/back" formnovalidate>${label}</button>` : `<span>${label}</span>`}</li>`).join('')}</ol>
  ${view.conflict ? `<div class="comparison"><h2>Сравните версии перед заменой</h2><p>В форме ниже сохранён ваш ввод. <a href="/" target="_blank">Показать текущие сохранённые версии в другой вкладке</a></p>
    ${view.latest ? `<h3>Рабочая подготовка, версия ${view.currentRevision}</h3>${comparisonTable(comparison, 'Сравнение рабочей подготовки', 'Рабочая подготовка совпадает с вашим вводом.')}` : ''}
    <h3>Сохранённое объявление, версия ${view.campaignRevision}</h3>${view.campaign ? comparisonTable(campaignComparison, 'Сравнение сохранённого объявления', 'Поля объявления совпадают с вашим вводом; его версия всё равно проверяется перед заменой.') : '<p>Сохранённого объявления пока нет.</p>'}
    <p>Это отдельные сохранённые версии. Проверьте обе перед заменой. Новое внешнее изменение снова остановит сохранение.</p></div>` : ''}
  <div class="flow-layout"><form id="campaign-form" class="form-panel plan-form" method="post" action="/preparation/${step === 1 ? 'entry' : step === 2 ? 'confirm-profile' : step === 3 ? 'offer' : 'confirm'}"
    data-plan="1" data-step="${step}" data-scope="${e(scope)}" data-restore="1" data-restored="${view.restored ? '1' : '0'}" data-saved="${view.acknowledged ? '1' : '0'}" data-ack="${view.acknowledged ? '1' : '0'}" data-dirty="${view.unsaved || view.errors || view.conflict ? '1' : '0'}">
    ${hidden('policyHash', policyHash)}${hidden('preparationRevision', view.saved.revision)}${hidden('revision', p.baseCampaignRevision)}${hidden('formStep', step)}
    ${Object.entries(values).filter(([key]) => !visible.includes(key as any)).map(([key, val]) => hidden(key, val)).join('')}
    ${step === 1 ? `<h2>Бизнес и условия</h2><p class="muted">Что вы предлагаете и где. Цель — пожелание бизнеса; измерение Метрики настраивается отдельно.</p>
      ${post('example', 'Заполнить вымышленным примером', false, ' formnovalidate')}${inputField('description', 'Укажите товары или услуги, важные условия и исключения. Сайт автоматически не читается.')}
      <div class="field-grid">${inputField('url')}${inputField('region', 'Точное название города или региона.')}</div>${inputField('goal', 'Например, обращения по ремонту холодильников. Это ещё не измеренная цель Метрики.')}
      <div class="field-grid">${inputField('budget', 'Лимит на весь выбранный период. Сохранение не расходует рекламный бюджет.')}${inputField('period')}</div>
      <div class="actions">${post('entry', 'Сохранить и продолжить', true)}</div>` : ''}
    ${step === 2 ? `<h2>Что мы поняли</h2><p class="source-note">${source}. Неподтверждённые сведения не попадают в план.</p>${inputField('description', 'Здесь можно уточнить исходный факт без повторного запроса модели.')}
      <details${!profile ? ' open' : ''}><summary>Предложить понимание с DeepSeek</summary><p>Один платный разбор только описания. Адрес сайта, бюджет и Метрика не отправляются. Ответ до 1800 токенов; стоимость зависит от провайдера.</p>
        ${!view.ai ? '<p class="source-note">DeepSeek не подключён. Введите понимание вручную ниже; рабочий ввод сохранится. Для локального подключения используйте Connect-PhraseAI.ps1 из инструкции.</p>' : check('aiConsent', 'Разрешаю передать это описание DeepSeek для одного платного разбора.')}
        ${post('profile', 'Получить предложение DeepSeek', false, !view.ai ? ' disabled' : '')}
        ${freshProposal && p.profile?.value.offers.length ? `${hidden('runId', view.run!.id)}<p>Ручные исправления сохранены. Сохранённый ответ модели можно применить отдельно.</p>${post('use-profile', 'Использовать сохранённое предложение')}` : ''}</details>
      ${hidden('profileEditor', 'yes')}${Array.from({ length: 3 }, (_, i) => {
        const offer = profile?.offers[i];
        const card = `<fieldset class="profile-offer"><legend>Предложение ${i + 1}</legend>${hidden('offerId' + i, offer?.id ?? `offer-${i + 1}`)}${field('offer' + i, 'Что вы предлагаете', offer?.name ?? '', 'input', 'Отдельный товар, услуга или обучение.', false, 70)}
          ${field('evidence' + i, 'Цитата из описания', offer?.evidence ?? '', 'textarea', 'Точный фрагмент текста выше, который подтверждает предложение.', false, 240)}
          <div class="field"><label for="plan-kind${i}">Тип предложения</label><select id="plan-kind${i}" name="kind${i}">${[['service', 'Услуга'], ['product', 'Товар'], ['training', 'Обучение']].map(([v,l]) => `<option value="${v}"${offer?.kind === v ? ' selected' : ''}>${l}</option>`).join('')}</select></div>
          <label class="check"><input type="checkbox" name="delivery${i}" value="yes"${offer?.delivery ? ' checked' : ''}>Есть доставка — она явно указана в цитате</label>
          <details><summary>Синонимы и направления поиска</summary>${field('aliases' + i, 'Синонимы', offer?.aliases.join('\n') ?? '', 'textarea', 'До двух синонимов, каждый с новой строки.', false, 150)}${field('seeds' + i, 'Направления поиска', offer?.seeds.join('\n') ?? '', 'textarea', 'До двух коротких фраз. Если оставить пустым, используется название.', false, 220)}</details></fieldset>`;
        return i === 0 || offer ? card : `<details><summary>Добавить ещё одно связанное предложение</summary>${card}</details>`;
      }).join('')}
      <details><summary>Бренды, исключения и неизвестное</summary>${field('ownBrands', 'Собственные бренды', profile?.ownBrands.join('\n') ?? '', 'textarea', 'Только буквально указанные в описании, до трёх.')}
        ${Array.from({length:10}, (_, i) => { const x = profile?.exclusions[i]; return `<div${!x && i > 0 ? ' class="optional-exclusion"' : ''}>${field('exclude' + i, 'Исключение ' + (i + 1), x?.phrase ?? '', 'input', 'Товар или условие, которые вы не предлагаете.', false, 100)}${field('excludeEvidence' + i, 'Цитата для исключения ' + (i + 1), x?.evidence ?? '', 'input', 'Точный фрагмент с «не», «без» или «кроме».', false, 240)}</div>`; }).join('')}
        ${field('uncertainty', 'Что пока неизвестно', profile?.uncertainty.join('\n') ?? '', 'textarea', 'До четырёх пунктов. Они не становятся обещаниями.')}</details>
      <p class="hint">Аудитория: люди, которые ищут эти товары или услуги в выбранном регионе. Возраст и интересы не выдумываются.</p>
      <div class="actions">${back(1)}${post('confirm-profile', 'Подтвердить понимание', true)}</div>` : ''}
    ${step === 3 ? `<h2>Рекламное предложение</h2><p class="source-note">${profileCurrent ? 'Факты подтверждены.' : 'Понимание требует повторной проверки.'} ${e(p.input.region)} · ${e(p.goal)}</p>
      <p>Покажем объявление людям, которые ищут ваши подтверждённые товары или услуги. Ручной текст остаётся вашим.</p>${inputField('title')}${inputField('adText')}
      <details><summary>Исследовать спрос и подобрать фразы</summary><p>Направления: ${p.profile?.value ? researchRequests(p.profile.value).map(r => e(r.seed)).join('; ') : 'сначала подтвердите понимание'}.</p>
        <p>Не более ${p.profile?.value ? researchRequests(p.profile.value).length : 0} новых запросов Wordstat; сохранённые полные ответы по тому же региону используются без оплаты в течение суток. Одна оценка DeepSeek до 80 кандидатов/до12000 выходных токенов (новый структурный контракт). Остальные остаются для ручного просмотра.</p>
        ${!view.wordstat || !view.ai ? '<p class="source-note">Полное исследование не подключено. Можно сохранить проверенный ручной список ниже.</p>' : ''}
        ${check('researchConsent', 'Разрешаю платные запросы Wordstat по показанным направлениям и региону.')}${check('judgeConsent', 'Разрешаю одну платную оценку предложений, объявления, региона и до 80 фраз в DeepSeek.')}
        ${post('research', 'Исследовать спрос', false, !view.wordstat || !view.ai ? ' disabled' : '')}${view.run && ['research','derived','rejudge'].includes(view.run.kind) && usable && view.run.status === 'stopped' && view.run.plan.strategy.requests.some(r => r.phase === 'ready') && !view.run.attempts.some(a => ['pending', 'unknown'].includes(a.status)) ? hidden('runId', view.run.id) + '<p>Есть неотправленные направления. Их можно продолжить с согласиями выше; уже отправленные не повторятся.</p>' + post('continue-research', 'Продолжить только неотправленные запросы') : ''}</details>
      ${view.run && ['research','derived','rejudge'].includes(view.run.kind) ? `<p class="source-note">${usable ? 'Сохранённое исследование' : 'Исследование относится к прежним данным'}: получено ${view.run.plan.strategy.requests.filter(r => r.phase === 'complete').length} из ${view.run.plan.strategy.requests.length} ответов; оценено ${view.run.plan.strategy.evaluated ?? 0} из ${view.run.plan.candidates.length} кандидатов.</p><p class="hint">${e(view.run.plan.notice)} ${e(view.run.plan.strategy.note ?? '')}</p>` : ''}
      ${view.run && ['research','derived','rejudge'].includes(view.run.kind) ? `<p class="source-note">Правила: ${e(view.run.plan.policyHash === policyHash ? 'текущие' : 'прежняя версия — требуется пересмотр')}. ${view.run.derivation ? `Локальный пересмотр: ${e(view.run.derivation.processedAt)}. Исходный run: ${e(view.run.derivation.sourceRunId)}.` : ''} Даты Wordstat сохраняются; новая оценка их не обновляет.</p>${view.run.kind==='rejudge' && view.run.status!=='complete' ? post('recover-rejudge','Восстановить полученный ответ из журнала') : ''}${post('reprocess','Пересмотреть сохранённые ответы — без запросов',false,view.cached ? '' : ' disabled')}<p>Отдельная оценка использует прежние profile/Wordstat. Прежние разрешения исчерпаны; настоящий вызов возможен только с новым разрешением.</p>${check('rejudgeConsent','Согласен на одну новую оценку до80 сохранённых фраз по новому контракту, без повторов profile/Wordstat.')}${post('rejudge','Оценить сохранённые фразы новым контрактом',false,view.cached && view.ai ? '' : ' disabled')}` : ''}
      ${hidden('selectionEditor', 'yes')}${candidates.length ? `<details open><summary>Фразы с причинами выбора (${candidates.length})</summary><ul class="phrase-list">${candidates.map((c,i) => `<li class="phrase-row"><label class="check" for="candidate-${i}"><input type="checkbox" id="candidate-${i}" name="selected" value="${e(c.phrase)}"${selected.includes(c.phrase) ? ' checked' : ''}${c.decision === 'exclude' ? ' disabled' : ''}><span>${e(c.phrase)}<br><span class="hint">${e(researchCandidateReason(view.run!, c))}${c.assessment?.model ? `<br>Оценка модели: ${e((c.assessment.model as any).reason)} · модельное решение ${e((c.assessment.model as any).decision)}` : ''}${c.assessment?.geoQualifierOverrides?.map(override=>`<br>${e(override.reason)}`).join('') ?? ''} · ${c.count === null ? 'Нет сопоставимой частоты' : `Частота ${e(c.count)}`} · получено ${e(new Date(c.evidence[0]?.at ?? view.run!.plan.at).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' }))} МСК</span></span></label></li>`).join('')}</ul></details>` : ''}
      ${field('phrases', candidates.length ? 'Добавить фразы вручную' : 'По каким фразам вас ищут', p.selection.phrases.filter(s => !candidates.some(c => c.phrase === s)).join('\n'), 'textarea', 'От 1 до 30 фраз в общем списке; по одной на строку, до 7 слов/100 символов, без операторов.')}
      <details><summary>Что исключить из поиска</summary>${field('negatives', 'Минус-фразы', p.selection.negatives.join('\n'), 'textarea', 'По одной на строку. Подтверждённые исключения бизнеса добавятся автоматически.')}</details>
      ${check('manualReview', 'Я проверил спорные и добавленные вручную фразы. Ручной список не доказывает спрос или эффективность.')}
      <div class="actions">${back(2)}${post('offer', 'Проверить план', true)}</div>` : ''}
    ${step === 4 ? `<h2>Проверка и создание</h2><p class="source-note">${view.current ? 'Подтверждённая версия готова для проверки параметров Директа.' : 'Проверьте сводку перед подтверждением. Реальных объектов пока не создаём.'}</p>
      <dl class="preview-meta"><div><dt>Предложения</dt><dd>${p.profile?.value.offers.map(o => e(o.name)).join(', ') ?? 'Не подтверждены'}</dd></div><div><dt>Цель бизнеса</dt><dd>${e(p.goal)}</dd></div><div><dt>Регион</dt><dd>${e(p.input.region)}</dd></div><div><dt>Общий лимит</dt><dd>${e(p.input.budget)} ₽ за ${e(p.input.period)} дней</dd></div><div><dt>Фразы</dt><dd>${p.selection.phrases.map(e).join('<br>')}</dd></div><div><dt>Источник</dt><dd>${p.selection.source === 'strategy' ? 'Wordstat и смысловая оценка' : 'Проверенный ручной список; спрос не измерен'}</dd></div><div><dt>Исключения</dt><dd>${p.selection.negatives.map(e).join(', ') || 'Нет'}</dd></div></dl>
      <p>Поиск · одна группа и объявление · без показов. ${budgetNote}</p>
      ${!profileCurrent || p.selection.checkedHash !== selectionHash(p) ? '<p class="field-error">Факты или рекламное предложение изменились. Вернитесь к проверке соответствующего шага.</p>' : ''}
      ${!view.current ? `${check('confirmPlan', 'Я проверил факты, объявление, фразы и условия. Подтверждаю этот план.')}` : `<p>План <code>${e(view.plan!.id)}</code> · версия ${view.plan!.preparationRevision}. <a href="#direct">${direct?.enabled ? 'К параметрам Директа' : 'Подключение Директа потребуется для создания'}</a></p>`}
      <div class="actions">${back(3, 'Изменить предложение')}${!view.current ? post('confirm', 'Подтвердить план', true) : ''}</div>` : ''}
    ${view.conflict ? `${hidden('currentRevision', view.currentRevision ?? view.saved.revision)}${hidden('currentCampaignRevision', view.campaignRevision)}${check('replace', 'Я сравнил актуальные данные и хочу сохранить мой вариант вместо них.')}${post('resolve', 'Сохранить мой вариант после сравнения')}` : ''}
    <div class="actions">${post('save', 'Сохранить и вернуться позже', false, ' formnovalidate')}</div>
    <p id="local-recovery-note" class="hint">Рабочий ввод сохраняется по кнопке. Подтверждённый план изменяется только после проверки всей сводки.</p>
  </form><aside class="preview-panel" aria-label="План и объявление"><p class="preview-label">Предпросмотр объявления</p><div class="ad-preview" id="${p.input.title ? 'campaign-preview' : 'plan-placeholder'}"><span class="ad-tag">Локальный план</span><p class="ad-title" data-preview="title">${e(p.input.title || 'Заголовок появится после подтверждения понимания')}</p><p data-preview="adText">${e(p.input.adText)}</p><p class="ad-url" data-preview="url">${e(p.input.url)}</p></div><p class="hint">${direct?.enabled ? 'Кабинет подключён. Создание потребует отдельного подтверждения.' : 'Директ не подключён. Подготовку можно сохранить.'}</p>
    ${profile ? `<details><summary>Факты и основания</summary>${profile.offers.map(o => `<p><strong>${e(o.name)}</strong><br>«${e(o.evidence)}»</p>`).join('')}</details>` : ''}
    ${view.runs.length ? `<details><summary>Попытки и сохранённые ответы (${view.runs.length})</summary>${view.runs.map(r => `<article><p>${r.kind === 'profile' ? 'Понимание' : r.kind === 'legacy' ? 'Прежний подбор' : 'Исследование'} · ${r.status === 'running' ? 'Есть незавершённое намерение; повтор остановлен' : r.status === 'stopped' ? 'Получены не все ответы' : 'Ответы сохранены'}</p><ul>${r.attempts.map(a => `<li>${a.kind} — ${a.status === 'succeeded' ? 'Ответ сохранён' : a.status === 'pending' || a.status === 'unknown' ? 'Результат неизвестен, повтор запрещён' : a.status === 'rejected' ? 'Получен неполный или некорректный ответ' : 'Провайдер отказал; проверьте доступ или лимит'}${a.error ? ' · ' + e(a.error) : ''}</li>`).join('')}</ul></article>`).join('')}<a href="/preparation/research.json">Скачать свои данные подготовки</a></details>` : ''}
    <p><a href="/history">История объявлений и операций</a></p></aside></div>
    ${step === 4 && view.current && direct?.enabled && !direct.needsReconcile && !hasUnresolvedDirect(direct.state) && (!direct.state || direct.state.complete || Object.values(direct.state.steps).every(s => s.phase === 'ready')) ? `<section class="direct-panel" id="plan-direct-parameters"><h2>Проверить параметры Директа</h2><p>План подтверждён. Это чтение настроек и локальная подготовка; рекламные объекты создаются следующим отдельным действием.</p><form method="post" action="/direct/prepare">${hidden('revision', view.plan!.campaignRevision)}${hidden('campaignPlanId', view.plan!.id)}${field('name', 'Название кампании', direct.input?.name || 'Тестовый план', 'input', 'До 100 символов.', true, 100)}${direct.ownChief ? `<p>В API: ${e(view.plan!.draft.budget)} ₽ за ${e(view.plan!.draft.period)} дней, без автопродления. Отдельный недельный бюджет не задаётся.</p><div class="field"><label for="direct-start-date">Начало бюджетного периода, МСК</label><input type="date" id="direct-start-date" name="startDate" required value="${e(direct.input?.startDate || new Date(Date.now()+7*86400000).toISOString().slice(0,10))}"></div>${direct.state?.complete?check('newRun','Подготовить отдельный новый набор. Прежний набор и его история сохранятся.'):''}` : field('weekly', 'Недельный бюджет API, ₽', direct.input?.weekly || '300', 'input', 'Отдельный параметр API, от 300 до 100 000 ₽. Не ограничивает общий фактический расход лимитом плана.', true, 6)}<button class="${direct.state?.campaignPlanId === view.plan!.id ? 'secondary' : 'primary'}" type="submit">Проверить параметры Директа</button></form></section>` : ''}`;
}
